window.AUTH=window.AUTH||{};window.AUTH["04-623"]={"d":"04-623","id":"2005/04-623","n":"Gonzales v. Oregon","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the petitioners","date":"","url":"https://www.justice.gov/osg/media/227716/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/gonzales-v-oregon-reply-merits","n":49},{"k":"petitioner","label":"Brief for the petitioners","date":"","url":"https://www.justice.gov/osg/media/195021/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/gonzales-v-oregon-brief-merits","n":110}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep546/usrep546243/usrep546243.pdf","tr":true,"items":[{"t":"case","label":"Alaska Dep’t of Envtl. Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"0":"1, 2"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Cmtys. for a Great Or.","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Caron v. United States","cite":"514 U.S. 308","y":1998,"id":"1997/97-6270","sc":1,"sum":"The Court held that \"Massachusetts treats [Caron] as too dangerous to trust with handguns, though it accords this right to law-abiding citizens.","sumSrc":"Oyez","by":{"0":"13, 19","1":"21"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":22,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"2, 3"}},{"t":"case","label":"Chicago & N.W. Transp. Co. v. Kalo Brick & Tile Co.","cite":"450 U.S. 311","y":1981,"id":"1980/79-1336","sc":1,"sum":"The Interstate Commerce Act precludes a shipper from pressing a state-court action for damages against a regulated rail carrier when, as here, the ICC, in approving the carrier's application for abandonment, reaches the merits of the matters the shipper seeks to raise in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Christensen v. Harris County","cite":"519 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"op":3,"ar":2,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"City of Edmonds v. Oxford House, Inc.","cite":"514 U.S. 725","y":1995,"id":"1994/94-23","sc":1,"sum":"The Court held that Edmonds' zoning code definition of the term \"family\" is not a maximum occupancy restriction exempt from the FHA.","sumSrc":"Oyez","by":{"0":"17","1":"39"}},{"t":"case","label":"Department of Revenue v. ACF Indus., Inc.","cite":"510 U.S. 332","y":1994,"id":"1993/92-74","sc":1,"sum":"Section 11503 does not limit the States' discretion to exempt nonrailroad property, but not railroad property, from generally applicable ad valorem property taxes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Dickerson v. New Banner Inst., Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"sum":"The firearms disabilities imposed by §§ 922(g)(1) and (h)(1) apply to Kennison and were not removed by the expunction of the record of his guilty plea to the concealed weapon charge.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13","1":"27"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Elk Grove Unified Sch. Dist. v. Newdow","cite":"124 S. Ct. 2301","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Gibbons v. Ogden","cite":"22 U.S. 1","y":1824,"id":"1789-1850/22us1","sc":1,"ar":3,"sum":"The Court decided that the federal government has exclusive power over interstate commerce.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"op":5,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"17","1":"9, 13, 37, 38, 39"}},{"t":"case","label":"Gonzalez v. Raich","cite":"125 S. Ct. 2195","y":2004,"url":"https://www.courtlistener.com/c/S.%20Ct./125/2195/","sc":1,"by":{"0":"2, 3, 7, 8, 11, 14, 15, 16"}},{"t":"case","label":"Hillsborough County v. Automated Med. Labs., Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"op":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Hisquierdo v. Hisquierdo","cite":"439 U.S. 572","y":1979,"id":"1978/77-533","sc":1,"sum":"Benefits payable under the Act may not be divided under the community property law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Hodel v. Virginia Surface Mining & Reclamation Ass’n","cite":"452 U.S. 264","y":1981,"id":"1980/79-1538","sc":1,"sum":"In the context of a facial challenge, the Act is constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"39"}},{"t":"case","label":"Hyland v. Fukuda","cite":"580 F.2d 977","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/580/977/","by":{"0":"12"}},{"t":"case","label":"Jerome v. United States","cite":"318 U.S. 101","y":1943,"id":"scdb/1942-126","sc":1,"sum":"In § 2 (a) of the federal Bank Robbery Act, which provides that \"whoever shall enter or attempt to enter any bank, or any building used in whole or in part as a bank, with intent to commit in such bank or building, or part thereof, so used, any felony or larceny\" shall be subject to the penalty therein prescribed, the word \"felony\" embraces only offenses which are felonies under federal law and affect banks …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"25"}},{"t":"case","label":"Jin Fuey Moy v. United States","cite":"254 U.S. 189","y":1920,"id":"scdb/1920-019","sc":1,"sum":"1. In a case properly here on a constitutional question under Jud. Code, §238, the court retains its jurisdiction to decide other quest.ons presented, after the constitutional question has been settled in another case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13, 18"}},{"t":"case","label":"Kane v. Kulongoski","cite":"871 P.2d 993","y":1994,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/871/993/","by":{"0":"12","1":"6, 22, 44"}},{"t":"case","label":"Lambert v. Yellowley","cite":"272 U.S. 581","y":1926,"id":"scdb/1926-021","sc":1,"sum":"1. The provision of the National Prohibition Act that \"Not more than a pint of spirituous liquor to be taken internally shall be Argument for Appellant. prescribed for use by the same person within any period of ten days and no prescription shall be filled more than once,\" is \"appropriate legislation,\" within the meaning of the Eighteenth Amendment for enforcing its prohibition of the manufacture, sale, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"40"}},{"t":"case","label":"Linder v. United States","cite":"268 U.S. 5","y":1925,"id":"scdb/1924-117","sc":1,"ar":1,"sum":"1. Any provision of an act of Congress ostensibly enacted under power granted by the Constitution, not naturally and reasonably adapted to the effective exercise of such power but solely to the achievement of something plainly within tha power reserved to the States, is invalid and can. not be enforced.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19","1":"37, 40"}},{"t":"case","label":"Martin v. OSHRC","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"op":1,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19"}},{"t":"case","label":"National Cable & Telecomm. Ass’n v. Brand X Internet Servs.","cite":"125 S. Ct. 2688","y":2005,"id":"2004/04-277","sc":1,"op":2,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Robertson v. Methow Valley Citizens Council","cite":"490 U.S. 332","y":1989,"id":"1988/87-1703","sc":1,"sum":"The Forest Service is authorized by statute to manage national forests for, inter alia, recreational purposes. Because its decision to issue a recreational special use permit is a \"major Federal action\" within the meaning of the National Environmental Policy Act of 1969 (NEPA), that decision must be preceded by the preparation of an Environmental Impact Statement (EIS). After a Service study designated a particular …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Shatz v. United States Dep’t of Justice","cite":"873 F.2d 1089","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/1089/","by":{"0":"10"}},{"t":"case","label":"Solid Waste Agency v. United States Army Corps. of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"op":2,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"18","1":"9, 41"}},{"t":"case","label":"Thomas Jefferson Univ. v. Shalala","cite":"512 U.S. 504","y":1994,"id":"1993/93-120","sc":1,"op":1,"sum":"The Secretary's interpretation of the anti-redistribution principle is reasonable. Because its application suffices to deny reimbursement of the disputed costs in this case, there is no need to decide the validity of the Secretary's interpretation of the community support language.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 2","1":"21"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"op":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 18"}},{"t":"case","label":"United States v. Behrmann","cite":"258 U.S. 281","y":1922,"url":"https://supreme.justia.com/cases/federal/us/258/281/","sc":1,"by":{"0":"13, 15, 16, 18"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 213","y":2001,"id":"2000/99-1434","sc":1,"op":4,"sum":"Noting that an opinion receiving Skidmore deference may “claim the merit of its writer’s thoroughness, logic, and ex­ pertness, its ﬁt with prior interpretations, and any other 546US2 Unit: $U18 [09-04-08 12:21:03] PAGES PGT: OPIN sources of weight”.","sumSrc":"opinion","by":{"0":"2, 3, 8, 15"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers’ Coop.","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"op":1,"sum":"The Court held that there is no medical necessity exception to the Controlled Substances Act's prohibitions on manufacturing and distributing marijuana. \"The statute reflects a determination that marijuana has no medical benefits worthy of an exception, \" wrote Justice Thomas, therefore, \"medical necessity is not a defense to manufacturing and distributing marijuana.\" Justice John Paul Stevens' concurring opinion, which was joined by Justices David H. Souter and Ruth Bader Ginsburg, argued that \"[b]ecause necessity was raised in this case as a defense to distribution, the Court need not venture an opinion on whether the defense is available to anyone other than distributors.\" Justice Stephen G. Breyer took no part in the consideration or decision of the case.","sumSrc":"Oyez","by":{"0":"3, 7","1":"3, 12, 28, 41, 44"}},{"t":"case","label":"Verizon Communications, Inc. v. FCC","cite":"535 U.S. 467","y":2002,"id":"2001/00-511","sc":1,"sum":"The Court held that the FCC can require state commissions to set the rates charged by incumbents for leased elements on a forward-looking basis untied to the incumbents' investment and that the FCC can require incumbents to combine elements of their networks at the request of entrants.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Webb v. United States","cite":"249 U.S. 96","y":1919,"id":"scdb/1918-175","sc":1,"op":1,"sum":"The first sentence of § 2 of the Narcotic Drug Act of December 17, 1914, c. 1,38 Stat. 785, prohibits retail sales of morphine by druggists to persons who have no physician’s prescription, who have no order blank therefor and who cannot obtain an order blank because not of the class to which such blanks are allowed to be issued under. the act. P. 99. -.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16","1":"33, 19, 40"}},{"t":"case","label":"Will v. Michigan Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"0":"17"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(3)(A)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"0":"13"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"13"}},{"t":"usc","label":"18 U.S.C. § 2423","url":"https://www.law.cornell.edu/uscode/text/18/2423","subs":["(b)"],"by":{"0":"16"}},{"t":"usc","label":"18 U.S.C. § 1073","url":"https://www.law.cornell.edu/uscode/text/18/1073","by":{"0":"16"}},{"t":"usc","label":"18 U.S.C. § 1958","url":"https://www.law.cornell.edu/uscode/text/18/1958","subs":["(a)"],"by":{"0":"16"}},{"t":"usc","label":"18 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/18/2101","subs":["(a)(1)"],"by":{"0":"16"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","subs":["(1)","(2)","(6)"],"stext":{"head":"§801. Congressional findings and declarations: controlled substances","paras":[[0,"The Congress makes the following findings and declarations:"],[0,"(1) Many of the drugs included within this subchapter have a useful and legitimate medical purpose and are necessary to maintain the health and general welfare of the American people."],[0,"(2) The illegal importation, manufacture, distribution, and possession and improper use of controlled substances have a substantial and detrimental effect on the health and general welfare of the American people."],[0,"(3) A major portion of the traffic in controlled substances flows through interstate and foreign commerce. Incidents of the traffic which are not an integral part of the interstate or foreign flow, such as manufacture, local distribution, and possession, nonetheless have a substantial and direct effect upon interstate commerce because—"],[1,"(A) after manufacture, many controlled substances are transported in interstate commerce,"],[1,"(B) controlled substances distributed locally usually have been transported in interstate commerce immediately before their distribution, and"],[1,"(C) controlled substances possessed commonly flow through interstate commerce immediately prior to such possession."],[0,"(4) Local distribution and possession of controlled substances contribute to swelling the interstate traffic in such substances."],[0,"(5) Controlled substances manufactured and distributed intrastate cannot be differentiated from controlled substances manufactured and distributed interstate. Thus, it is not feasible to distinguish, in terms of controls, between controlled substances manufactured and distributed interstate and controlled substances manufactured and distributed intrastate."],[0,"(6) Federal control of the intrastate incidents of the traffic in controlled substances is essential to the effective control of the interstate incidents of such traffic."],[0,"(7) The United States is a party to the Single Convention on Narcotic Drugs, 1961, and other international conventions designed to establish effective control over international and domestic traffic in controlled substances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/801?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§801. Congressional findings and declarations: controlled substances","tname":"Food and Drugs","by":{"0":"2, 7","1":"21, 26, 45, 26"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(21)","(10)","(12)"],"stext":{"head":"§802. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) The term \"addict\" means any individual who habitually uses any narcotic drug so as to endanger the public morals, health, safety, or welfare, or who is so far addicted to the use of narcotic drugs as to have lost the power of self-control with reference to his addiction."],[0,"(2) The term \"administer\" refers to the direct application of a controlled substance to the body of a patient or research subject by—"],[1,"(A) a practitioner (or, in his presence, by his authorized agent), or"],[1,"(B) the patient or research subject at the direction and in the presence of the practitioner,"],[0,"whether such application be by injection, inhalation, ingestion, or any other means."],[0,"(3) The term \"agent\" means an authorized person who acts on behalf of or at the direction of a manufacturer, distributor, or dispenser; except that such term does not include a common or contract carrier, public warehouseman, or employee of the carrier or warehouseman, when acting in the usual and lawful course of the carrier's or warehouseman's business."],[0,"(4) The term \"Drug Enforcement Administration\" means the Drug Enforcement Administration in the Department of Justice."],[0,"(5) The term \"control\" means to add a drug or other substance, or immediate precursor, to a schedule under part B of this subchapter, whether by transfer from another schedule or otherwise."],[0,"(6) The term \"controlled substance\" means a drug or other substance, or immediate precursor, included in schedule I, II, III, IV, or V of part B of this subchapter. The term does not include distilled spirits, wine, malt beverages, or tobacco, as those terms are defined or used in subtitle E of the Internal Revenue Code of 1986."],[0,"(7) The term \"counterfeit substance\" means a controlled substance which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, number, or device, or any likeness thereof, of a manufacturer, distributor, or dispenser other than the person or persons who in fact manufactured, distributed, or dispensed such substance and which thereby falsely purports or is represented to be the product of, or to have been distributed by, such other manufacturer, distributor, or dispenser."],[0,"(8) The terms \"deliver\" or \"delivery\" mean the actual, constructive, or attempted transfer of a controlled substance or a listed chemical, whether or not there exists an agency relationship."],[0,"(9) The term \"depressant or stimulant substance\" means—"],[1,"(A) a drug which contains any quantity of barbituric acid or any of the salts of barbituric acid; or"],[1,"(B) a drug which contains any quantity of (i) amphetamine or any of its optical isomers; (ii) any salt of amphetamine or any salt of an optical isomer of amphetamine; or (iii) any substance which the Attorney General, after investigation, has found to be, and by regulation designated as, habit forming because of its stimulant effect on the central nervous system; or"],[1,"(C) lysergic acid diethylamide; or"],[1,"(D) any drug which contains any quantity of a substance which the Attorney General, after investigation, has found to have, and by regulation designated as having, a potential for abuse because of its depressant or stimulant effect on the central nervous system or its hallucinogenic effect."],[0,"(10) The term \"dispense\" means to deliver a controlled substance to an ultimate user or research subject by, or pursuant to the lawful order of, a practitioner, including the prescribing and administering of a controlled substance and the packaging, labeling or compounding necessary to prepare the substance for such delivery. The term \"dispenser\" means a practitioner who so delivers a controlled substance to an ultimate user or research subject."],[0,"(11) The term \"distribute\" means to deliver (other than by administering or dispensing) a controlled substance or a listed chemical. The term \"distributor\" means a person who so delivers a controlled substance or a listed chemical."],[0,"(12) The term \"drug\" has the meaning given that term by section 321(g)(1) of this title."],[0,"(13) The term \"felony\" means any Federal or State offense classified by applicable Federal or State law as a felony."],[0,"(14) The term \"isomer\" means the optical isomer, except as used in schedule I(c) and schedule II(a)(4). As used in schedule I(c), the term \"isomer\" means any optical, positional, or geometric isomer. As used in schedule II(a)(4), the term \"isomer\" means any optical or geometric isomer."],[0,"(15) The term \"manufacture\" means the production, preparation, propagation, compounding, or processing of a drug or other substance, either directly or indirectly or by extraction from substances of natural origin, or independently by means of chemical synthesis or by a combination of extraction and chemical synthesis, and includes any packaging or repackaging of such substance or labeling or relabeling of its container; except that such term does not include the preparation, compounding, packaging, or labeling of a drug or other substance in conformity with applicable State or local law by a practitioner as an incident to his administration or dispensing of such drug or substance in the course of his professional practice. The term \"manufacturer\" means a person who manufactures a drug or other substance."],[0,"(16)(A) Subject to subparagraph (B), the terms \"marihuana\" and \"marijuana\" mean all parts of the plant Cannabis sativa L., whether growing or not; the seeds thereof; the resin extracted from any part of such plant; and every compound, manufacture, salt, derivative, mixture, or preparation of such plant, its seeds or resin."],[0,"(B) The terms \"marihuana\" and \"marijuana\" do not include—"],[1,"(i) hemp, as defined in section 1639o of title 7; or"],[1,"(ii) the mature stalks of such plant, fiber produced from such stalks, oil or cake made from the seeds of such plant, any other compound, manufacture, salt, derivative, mixture, or preparation of such mature stalks (except the resin extracted therefrom), fiber, oil, or cake, or the sterilized seed of such plant which is incapable of germination."],[0,"(17) The term \"narcotic drug\" means any of the following whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"],[1,"(A) Opium, opiates, derivatives of opium and opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation. Such term does not include the isoquinoline alkaloids of opium."],[1,"(B) Poppy straw and concentrate of poppy straw."],[1,"(C) Coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed."],[1,"(D) Cocaine, its salts, optical and geometric isomers, and salts of isomers."],[1,"(E) Ecgonine, its derivatives, their salts, isomers, and salts of isomers."],[1,"(F) Any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subparagraphs (A) through (E)."],[0,"(18) The term \"opiate\" or \"opioid\" means any drug or other substance having an addiction-forming or addiction-sustaining liability similar to morphine or being capable of conversion into a drug having such addiction-forming or addiction-sustaining liability."],[0,"(19) The term \"opium poppy\" means the plant of the species Papaver somniferum L., except the seed thereof."],[0,"(20) The term \"poppy straw\" means all parts, except the seeds, of the opium poppy, after mowing."],[0,"(21) The term \"practitioner\" means a physician, dentist, veterinarian, scientific investigator, pharmacy, hospital, or other person licensed, registered, or otherwise permitted, by the United States or the jurisdiction in which he practices or does research, to distribute, dispense, conduct research with respect to, administer, or use in teaching or chemical analysis, a controlled substance in the course of professional practice or research."],[0,"(22) The term \"production\" includes the manufacture, planting, cultivation, growing, or harvesting of a controlled substance."],[0,"(23) The term \"immediate precursor\" means a substance—"],[1,"(A) which the Attorney General has found to be and by regulation designated as being the principal compound used, or produced primarily for use, in the manufacture of a controlled substance;"],[1,"(B) which is an immediate chemical intermediary used or likely to be used in the manufacture of such controlled substance; and"],[1,"(C) the control of which is necessary to prevent, curtail, or limit the manufacture of such controlled substance."],[0,"(24) The term \"Secretary\", unless the context otherwise indicates, means the Secretary of Health and Human Services."],[0,"(25) The term \"serious bodily injury\" means bodily injury which involves—"],[1,"(A) a substantial risk of death;"],[1,"(B) protracted and obvious disfigurement; or"],[1,"(C) protracted loss or impairment of the function of a bodily member, organ, or mental faculty."],[0,"(26) The term \"State\" means a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/802?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§802. Definitions","tname":"Food and Drugs","by":{"0":"21","1":"2, 15, 45, 2, 5, 15, 17"}},{"t":"usc","label":"21 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/21/811","subs":["(c)","(a)"],"stext":{"head":"§811. Authority and criteria for classification of substances","paras":[[0,"(a) Rules and regulations of Attorney General; hearing"],[0,"The Attorney General shall apply the provisions of this subchapter to the controlled substances listed in the schedules established by section 812 of this title and to any other drug or other substance added to such schedules under this subchapter. Except as provided in subsections (d) and (e), the Attorney General may by rule—"],[1,"(1) add to such a schedule or transfer between such schedules any drug or other substance if he—"],[2,"(A) finds that such drug or other substance has a potential for abuse, and"],[2,"(B) makes with respect to such drug or other substance the findings prescribed by subsection (b) of section 812 of this title for the schedule in which such drug is to be placed; or"],[1,"(2) remove any drug or other substance from the schedules if he finds that the drug or other substance does not meet the requirements for inclusion in any schedule."],[0,"Rules of the Attorney General under this subsection shall be made on the record after opportunity for a hearing pursuant to the rulemaking procedures prescribed by subchapter II of chapter 5 of title 5. Proceedings for the issuance, amendment, or repeal of such rules may be initiated by the Attorney General (1) on his own motion, (2) at the request of the Secretary, or (3) on the petition of any interested party."],[0,"(b) Evaluation of drugs and other substances"],[0,"The Attorney General shall, before initiating proceedings under subsection (a) to control a drug or other substance or to remove a drug or other substance entirely from the schedules, and after gathering the necessary data, request from the Secretary a scientific and medical evaluation, and his recommendations, as to whether such drug or other substance should be so controlled or removed as a controlled substance. In making such evaluation and recommendations, the Secretary shall consider the factors listed in paragraphs (2), (3), (6), (7), and (8) of subsection (c) and any scientific or medical considerations involved in paragraphs (1), (4), and (5) of such subsection. The recommendations of the Secretary shall include recommendations with respect to the appropriate schedule, if any, under which such drug or other substance should be listed. The evaluation and the recommendations of the Secretary shall be made in writing and submitted to the Attorney General within a reasonable time. The recommendations of the Secretary to the Attorney General shall be binding on the Attorney General as to such scientific and medical matters, and if the Secretary recommends that a drug or other substance not be controlled, the Attorney General shall not control the drug or other substance. If the Attorney General determines that these facts and all other relevant data constitute substantial evidence of potential for abuse such as to warrant control or substantial evidence that the drug or other substance should be removed entirely from the schedules, he shall initiate proceedings for control or removal, as the case may be, under subsection (a)."],[0,"(c) Factors determinative of control or removal from schedules"],[0,"In making any finding under subsection (a) of this section or under subsection (b) of section 812 of this title, the Attorney General shall consider the following factors with respect to each drug or other substance proposed to be controlled or removed from the schedules:"],[1,"(1) Its actual or relative potential for abuse."],[1,"(2) Scientific evidence of its pharmacological effect, if known."],[1,"(3) The state of current scientific knowledge regarding the drug or other substance."],[1,"(4) Its history and current pattern of abuse."],[1,"(5) The scope, duration, and significance of abuse."],[1,"(6) What, if any, risk there is to the public health."],[1,"(7) Its psychic or physiological dependence liability."],[1,"(8) Whether the substance is an immediate precursor of a substance already controlled under this subchapter."],[0,"(d) International treaties, conventions, and protocols requiring control; procedures respecting changes in drug schedules of Convention on Psychotropic Substances"],[0,"(1) If control is required by United States obligations under international treaties, conventions, or protocols in effect on October 27, 1970, the Attorney General shall issue an order controlling such drug under the schedule he deems most appropriate to carry out such obligations, without regard to the findings required by subsection (a) of this section or section 812(b) of this title and without regard to the procedures prescribed by subsections (a) and (b) of this section."],[0,"(2)(A) Whenever the Secretary of State receives notification from the Secretary-General of the United Nations that information has been transmitted by or to the World Health Organization, pursuant to article 2 of the Convention on Psychotropic Substances, which may justify adding a drug or other substance to one of the schedules of the Convention, transferring a drug or substance from one schedule to another, or deleting it from the schedules, the Secretary of State shall immediately transmit the notice to the Secretary of Health and Human Services who shall publish it in the Federal Register and provide opportunity to interested persons to submit to him comments respecting the scientific and medical evaluations which he is to prepare respecting such drug or substance. The Secretary of Health and Human Services shall prepare for transmission through the Secretary of State to the World Health Organization such medical and scientific evaluations as may be appropriate regarding the possible action that could be proposed by the World Health Organization respecting the drug or substance with respect to which a notice was transmitted under this subparagraph."],[0,"(B) Whenever the Secretary of State receives information that the Commission on Narcotic Drugs of the United Nations proposes to decide whether to add a drug or other substance to one of the schedules of the Convention, transfer a drug or substance from one schedule to another, or delete it from the schedules, the Secretary of State shall transmit timely notice to the Secretary of Health and Human Services of such information who shall publish a summary of such information in the Federal Register and provide opportunity to interested persons to submit to him comments respecting the recommendation which he is to furnish, pursuant to this subparagraph, respecting such proposal. The Secretary of Health and Human Services shall evaluate the proposal and furnish a recommendation to the Secretary of State which shall be binding on the representative of the United States in discussions and negotiations relating to the proposal."],[0,"(3) When the United States receives notification of a scheduling decision pursuant to article 2 of the Convention on Psychotropic Substances that a drug or other substance has been added or transferred to a schedule specified in the notification or receives notification (referred to in this subsection as a \"schedule notice\") that existing legal controls applicable under this subchapter to a drug or substance and the controls required by the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] do not meet the requirements of the schedule of the Convention in which such drug or substance has been placed, the Secretary of Health and Human Services after consultation with the Attorney General, shall first determine whether existing legal controls under this subchapter applicable to the drug or substance and the controls required by the Federal Food, Drug, and Cosmetic Act, meet the requirements of the schedule specified in the notification or schedule notice and shall take the following action:"],[1,"(A) If such requirements are met by such existing controls but the Secretary of Health and Human Services nonetheless believes that more stringent controls should be applied to the drug or substance, the Secretary shall recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance, pursuant to subsections (a) and (b) of this section, to apply to such controls."],[1,"(B) If such requirements are not met by such existing controls and the Secretary of Health and Human Services concurs in the scheduling decision or schedule notice transmitted by the notification, the Secretary shall recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance under the appropriate schedule pursuant to subsections (a) and (b) of this section."],[1,"(C) If such requirements are not met by such existing controls and the Secretary of Health and Human Services does not concur in the scheduling decision or schedule notice transmitted by the notification, the Secretary shall—"],[2,"(i) if he deems that additional controls are necessary to protect the public health and safety, recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance pursuant to subsections (a) and (b) of this section, to apply such additional controls;"],[2,"(ii) request the Secretary of State to transmit a notice of qualified acceptance, within the period specified in the Convention, pursuant to paragraph 7 of article 2 of the Convention, to the Secretary-General of the United Nations;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/811?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§811. Authority and criteria for classification of substances","tname":"Food and Drugs","by":{"0":"21","1":"4, 46, 15, 26, 28"}},{"t":"usc","label":"21 U.S.C. § 823","url":"https://www.law.cornell.edu/uscode/text/21/823","subs":["(a)(1)","(f)(1970)","(g)"],"stext":{"head":"§823. Registration requirements","paras":[[0,"(a) Manufacturers of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule I or II if he determines that such registration is consistent with the public interest and with United States obligations under international treaties, conventions, or protocols in effect on May 1, 1971. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule I or II compounded therefrom into other than legitimate medical, scientific, research, or industrial channels, by limiting the importation and bulk manufacture of such controlled substances to a number of establishments which can produce an adequate and uninterrupted supply of these substances under adequately competitive conditions for legitimate medical, scientific, research, and industrial purposes;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal and State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture of controlled substances, and the existence in the establishment of effective control against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(b) Distributors of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to distribute a controlled substance in schedule I or II unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective control against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(c) Manufacturers of marijuana for research purposes"],[0,"(1)(A) As it relates to applications to manufacture marijuana for research purposes, when the Attorney General places a notice in the Federal Register to increase the number of entities registered under this chapter to manufacture marijuana to supply appropriately registered researchers in the United States, the Attorney General shall, not later than 60 days after the date on which the Attorney General receives a completed application—"],[1,"(i) approve the application; or"],[1,"(ii) request supplemental information."],[0,"(B) For purposes of subparagraph (A), an application shall be deemed complete when the applicant has submitted documentation showing each of the following:"],[1,"(i) The requirements designated in the notice in the Federal Register are satisfied."],[1,"(ii) The requirements under this chapter are satisfied."],[1,"(iii) The applicant will limit the transfer and sale of any marijuana manufactured under this subsection—"],[2,"(I) to researchers who are registered under this chapter to conduct research with controlled substances in schedule I; and"],[2,"(II) for purposes of use in preclinical research or in a clinical investigation pursuant to an investigational new drug exemption under 355(i) 1 of this title."],[1,"(iv) The applicant will transfer or sell any marijuana manufactured under this subsection only with prior, written consent for the transfer or sale by the Attorney General."],[1,"(v) The applicant has completed the application and review process under subsection (a) for the bulk manufacture of controlled substances in schedule I."],[1,"(vi) The applicant has established and begun operation of a process for storage and handling of controlled substances in schedule I, including for inventory control and monitoring security in accordance with section 105 of the Medical Marijuana and Cannabidiol Research Expansion Act."],[1,"(vii) The applicant is licensed by each State in which the applicant will conduct operations under this subsection, to manufacture marijuana, if that State requires such a license."],[0,"(C) Not later than 30 days after the date on which the Attorney General receives supplemental information requested under subparagraph (A)(ii) with respect to an application, the Attorney General shall approve or deny the application."],[0,"(2) If an application described in this subsection is denied, the Attorney General shall provide a written explanation of the basis of denial to the applicant."],[0,"(d) Limits of authorized activities"],[0,"Registration granted under subsections (a) and (b) of this section shall not entitle a registrant to (1) manufacture or distribute controlled substances in schedule I or II other than those specified in the registration, or (2) manufacture any quantity of those controlled substances in excess of the quota assigned pursuant to section 826 of this title."],[0,"(e) Manufacturers of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule III, IV, or V compounded therefrom into other than legitimate medical, scientific, or industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture, distribution, and dispensing of controlled substances, and the existence in the establishment of effective controls against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(f) Distributors of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to distribute controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(g) Research by practitioners; pharmacies; research applications; construction of Article 7 of the Convention on Psychotropic Substances"],[0,"(1) The Attorney General shall register practitioners (including pharmacies, as distinguished from pharmacists) to dispense, or conduct research with, controlled substances in schedule II, III, IV, or V and shall modify the registrations of pharmacies so registered to authorize them to dispense controlled substances by means of the Internet, if the applicant is authorized to dispense, or conduct research with respect to, controlled substances under the laws of the State in which he practices. The Attorney General may deny an application for such registration or such modification of registration if the Attorney General determines that the issuance of such registration or modification would be inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(A) The recommendation of the appropriate State licensing board or professional disciplinary authority."],[1,"(B) The applicant's experience in dispensing, or conducting research with respect to controlled substances."],[1,"(C) The applicant's conviction record under Federal or State laws relating to the manufacture, distribution, or dispensing of controlled substances."],[1,"(D) Compliance with applicable State, Federal, or local laws relating to controlled substances."],[1,"(E) Such other conduct which may threaten the public health and safety."],[0,"Separate registration under this part for practitioners engaging in research with controlled substances in schedule II, III, IV, or V, who are already registered under this part in another capacity, shall not be required."],[0,"(2)(A) Registration applications by practitioners wishing to conduct research with controlled substances in schedule I shall be referred to the Secretary, who shall determine the qualifications and competency of each practitioner requesting registration, as well as the merits of the research protocol. The Secretary, in determining the merits of each research protocol, shall consult with the Attorney General as to effective procedures to adequately safeguard against diversion of such controlled substances from legitimate medical or scientific use. Registration for the purpose of bona fide research with controlled substances in schedule I by a practitioner deemed qualified by the Secretary may be denied by the Attorney General only on a ground specified in section 824(a) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/823?type=usc&year=mostrecent&link-type=html"},"op":14,"sum":"Stating that the Attorney General shall register practitioners who dispense drugs for narcotics treat­ ment when the Secretary has determined the applicant is qualiﬁed to treat addicts and the Attorney General has con­ 546US2 Unit: $U18 [09-04-08 12:21:03] PAGES PGT: OPIN cluded the applicant will comply with recordkeeping and se­ curity regulations.","sumSrc":"opinion","head":"§823. Registration requirements","tname":"Food and Drugs","by":{"0":"21, 21","1":"16, 46, 2, 10, 15, 34, 46, 49, 10, 10, 49, 10, 46, 34, 49"}},{"t":"case","label":"Alliance for Cannabis Therapeutics v. DEA","cite":"15 F.3d 1131","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/15/1131/","sum":"Upholding DEA’s refusal to reschedule marijuana as supported by substantial evidence.","sumSrc":"brief:1","by":{"1":"21, 29"}},{"t":"case","label":"Asgrow Seed Co. v. Winterboer","cite":"513 U.S. 179","y":1995,"id":"1994/92-2038","sc":1,"sum":"The Court held that a farmer may sell for reproductive purposes only such seed as he has saved for the purpose of replanting his own fields. While the statute allows farmers to save seed to replant and then sell that saved seed to other farmers for planting, the statute prohibits growing protected seed as a \"step in marketing\" it as seed for planting.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"op":15,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"California Div. of Labor Standards Enforcement v. Dillingham Contrs. N.A., Inc.","cite":"519 U.S. 316","y":1997,"id":"1996/95-789","sc":1,"op":3,"sum":"Authored by Justice Clarence Thomas, the Court ruled that California's prevailing wage law does not \"relate to\" employee benefit plans, and thus is not preempted by the Employee Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"California Fed. Sav. & Loan Ass’n v. Guerra","cite":"479 U.S. 272","y":1987,"id":"1986/85-494","sc":1,"sum":"The judgment is affirmed. 758 F. 2d 390, affirmed. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts I, II, III-B, III-C, and IV, concluding that § 12945(b)(2) is not pre-empted by Title VII, as amended by the PDA, because it is not inconsistent with the purposes of Title VII nor does it require the doing of an act that is unlawful under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Gately v. Massachusetts","cite":"2 F.3d 1221","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/2/1221/","sum":"Noting that Gregory is limited to protecting “a core function going to the ‘heart of representative government’”.","sumSrc":"brief:1","by":{"1":"39"}},{"t":"case","label":"Gettman v. DEA","cite":"290 F.3d 430","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/290/430/","sum":"Explaining CSA procedures for rescheduling a controlled substance.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Gooding v. United States","cite":"416 U.S. 430","y":1974,"id":"1973/72-6902","sc":1,"sum":"Petitioner, charged with illegal possession of drugs, made a motion to suppress the physical evidence seized in petitioner's apartment on February 12, 1971, at 9:30 p. m. by District of Columbia police officers pursiiant to a magistrate's search warrant. Although no provisions of the D. C. Code were explicitly referred to, petitioner apparently contended, inter alia, that the warrant was executed in the nighttime in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Hammer v. Dagenhart","cite":"247 U.S. 251","y":1918,"id":"1900-1940/247us251","sc":1,"sum":"A case in which the Court deemed the Keating-Owen Child Labor Act unconstitutional because Congress does not have control over the commerce of goods produced by child labor.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1976,"id":"1995/95-754","sc":1,"op":2,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"1":"42, 43"}},{"t":"case","label":"Minor v. United States","cite":"396 U.S. 87","y":1969,"id":"1969/189","sc":1,"sum":"Petitioner in No. 189 was convicted of selling heroin to an undercover agent not pursuant to a written order on an official form, in violation of § 2 of the Harrison Narcotics Act, 26 U. S. C. § 4705 (a). In No. 271, petitioner was convicted of selling marihuana to an agent who did not have the official order form required by § 6 of the Marihuana Tax Act, 26 U. S. C. § 4742 (a). The Court of Appeals affirmed both …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Mississippi Band of Choctaw Indians v. Holyfield","cite":"490 U.S. 30","y":1989,"id":"1988/87-980","sc":1,"op":3,"sum":"The twins were \"domiciled\" on the Tribe's reservation within the meaning of the ICWA's exclusive tribal jurisdiction provision, and the Chancery Court was, accordingly, without jurisdiction to enter the adoption decree.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10, 11, 25"}},{"t":"case","label":"Reina v. United States","cite":"364 U.S. 507","y":1960,"id":"1960/29","sc":1,"sum":"The conviction is sustained. '","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Reves v. Ernst & Young","cite":"494 U.S. 56","y":1990,"id":"1989/88-1480","sc":1,"sum":"The demand notes issued by the Co-Op fall under the \"note\" category of instruments that are \"securities.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Robbins v. Footer","cite":"553 F.2d 123","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/553/123/","sum":"Rejecting locality rule in the District of Columbia for similar reasons and, on that basis, vacating and remanding district court’s disqualification of an expert witness who was not adequately expert in local practices.","sumSrc":"brief:1","by":{"1":"36"}},{"t":"case","label":"Salt Lake Tribune Publ’g Co. v. Management Planning, Inc.","cite":"390 F.3d 684","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/390/684/","by":{"1":"25"}},{"t":"case","label":"Trawick v. DEA","cite":"861 F.2d 72","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/861/72/","by":{"1":"21"}},{"t":"case","label":"United States v. Chin","cite":"795 F.2d 496","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/795/496/","by":{"1":"17"}},{"t":"case","label":"United States v. Daniel","cite":"3 F.3d 775","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/3/775/","op":2,"by":{"1":"16, 17, 32"}},{"t":"case","label":"United States v. Darby","cite":"312 U.S. 100","y":1941,"id":"1940-1955/312us100","sc":1,"sum":"The Court held that the Fair Labor Standards Act complied with the Commerce Clause, giving Congress the ability to regulate interstate commerce.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"United States v. Doremus","cite":"249 U.S. 86","y":1919,"id":"scdb/1918-174","sc":1,"sum":"While Congress may not exertauthority which is wholly reserved to the States, the power conferred by the Constitution to levy excise taxes, uniform throughout'the United States, is to be exercised at the discretion of-Congress; and, where the provisions of the law enacted have some reasonable relation to this power, the fact that they may have been impelled by a motive, or may accomplish a purpose, other than the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"United States v. Hammond","cite":"781 F.2d 1536","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/781/1536/","by":{"1":"17"}},{"t":"case","label":"United States v. Hayes","cite":"794 F.2d 1348","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/1348/","by":{"1":"32"}},{"t":"case","label":"United States v. Hughes","cite":"895 F.2d 1135","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/1135/","by":{"1":"17"}},{"t":"case","label":"United States v. Jamieson","cite":"806 F.2d 949","y":1986,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/806/949/","by":{"1":"16"}},{"t":"case","label":"United States v. Kaplan","cite":"895 F.2d 618","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/618/","by":{"1":"16"}},{"t":"case","label":"United States v. Kennedy","cite":"107 Fed. Appx. 518","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./107/518/","by":{"1":"32"}},{"t":"case","label":"United States v. Kirk","cite":"584 F.2d 773","y":1978,"url":"https://www.courtlistener.com/c/F.2d/584/773/","by":{"1":"17"}},{"t":"case","label":"United States v. Leal","cite":"75 F.3d 219","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/75/219/","sum":"Rejecting a pharmacist’s defense that state law imposed no duty to identify suspicious prescriptions because “[w]hether state law imposes an equivalent civil or criminal duty is irrelevant” to whether the pharmacist violated his “federal duty” under the CSA.","sumSrc":"brief:1","by":{"1":"32, 33, 35, 42"}},{"t":"case","label":"United States v. Lot 5, Fox Grove","cite":"23 F.3d 359","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/23/359/","sum":"Noting that “the Gregory plain statement preemption rule is limited to federal laws impacting a state’s self-identification as a sovereignty”.","sumSrc":"brief:1","by":{"1":"39"}},{"t":"case","label":"United States v. Moore","cite":"423 U.S. 122","y":1975,"id":"1975/74-759","sc":1,"op":7,"sum":"Noting that in enacting the addiction-treatment provisions, Congress sought to change the fact “that ‘criminal prosecutions’ in the past had turned on the opinions of federal prosecutors”.","sumSrc":"opinion","by":{"1":"passim"}},{"t":"case","label":"United States v. Nelson","cite":"383 F.3d 1227","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/1227/","sum":"Noting that “there is considerable room to doubt” whether the phrases “outside the usual course of medical practice” and “without legitimate medical purpose” have different meanings.","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"United States v. Norris","cite":"780 F.2d 1207","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/780/1207/","by":{"1":"32"}},{"t":"case","label":"United States v. Pelzer","cite":"312 U.S. 399","y":1941,"id":"scdb/1940-108","sc":1,"sum":"1. Decided in part upon authority of Helvering v. Hutchings, ante, p. 393. P.,401.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Plesons","cite":"560 F.2d 890","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/560/890/","by":{"1":"17"}},{"t":"case","label":"United States v. Rosenberg","cite":"515 F.2d 190","y":1975,"url":"https://www.courtlistener.com/c/F.2d/515/190/","op":1,"sum":"Rejecting physician’s defense against CSA prosecution that prescriptions were not impermissible under state law, explaining that “[t]he question of whether federal criminal laws have been violated is a federal issue to be determined in federal courts”.","sumSrc":"brief:1","by":{"1":"17, 32, 35, 42"}},{"t":"case","label":"United States v. Tran Trong Cuong","cite":"18 F.3d 1132","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/18/1132/","sum":"Stating the “legitimate medical purpose” standard is, if anything, more favorable to the defendant than the standard stated in Moore.","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"United States v. Turley","cite":"352 U.S. 407","y":1957,"id":"1956/289","sc":1,"sum":"In the National Motor Vehicle Theft Act, 18 U. S. C. § 2312, which makes it a federal crime to transport in interstate or foreign commerce a motor vehicle \"knowing the same to have been stolen,\" the word \"stolen\" is not limited to takings which amount to common-law larceny, but it includes all takings of motor vehicles with a criminal intent to deprive the owner of the rights and benefits of ownership.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Vamos","cite":"797 F.2d 1146","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/797/1146/","by":{"1":"32"}},{"t":"case","label":"Vacco v. Quill","cite":"521 U.S. 793","y":1997,"id":"1996/95-1858","sc":1,"op":1,"sum":"Employing a rationality test to examine the guarantees of the Equal Protection Clause, the Court held that New York's ban was rationally related to the state's legitimate interest in protecting medical ethics, preventing euthanasia, shielding the disabled and terminally ill from prejudice which might encourage them to end their lives, and, above all, the preservation of human life.","sumSrc":"Oyez","by":{"1":"20, 22"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"op":3,"ar":58,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"8, 21, 22, 23, 39"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"43, 44"}},{"t":"law","label":"Pub. L. No. 105-12","url":"https://www.govinfo.gov/link/plaw/105/public/12","by":{"1":"24"}},{"t":"usc","label":"21 U.S.C. § 830","url":"https://www.law.cornell.edu/uscode/text/21/830","subs":["(b)(3)","(b)(3)(A)(ii)","(b)(3)(D)(iv)"],"stext":{"head":"§830. Regulation of listed chemicals and certain machines","paras":[[0,"(a) Record of regulated transactions"],[0,"(1) Each regulated person who engages in a regulated transaction involving a listed chemical, a tableting machine, or an encapsulating machine shall keep a record of the transaction for two years after the date of the transaction."],[0,"(2) A record under this subsection shall be retrievable and shall include the date of the regulated transaction, the identity of each party to the regulated transaction, a statement of the quantity and form of the listed chemical, a description of the tableting machine or encapsulating machine, and a description of the method of transfer. Such record shall be available for inspection and copying by the Attorney General."],[0,"(3) It is the duty of each regulated person who engages in a regulated transaction to identify each other party to the transaction. It is the duty of such other party to present proof of identity to the regulated person. The Attorney General shall specify by regulation the types of documents and other evidence that constitute proof of identity for purposes of this paragraph."],[0,"(b) Reports to Attorney General"],[0,"(1) Each regulated person shall report to the Attorney General, in such form and manner as the Attorney General shall prescribe by regulation—"],[1,"(A) any regulated transaction involving an extraordinary quantity of a listed chemical, an uncommon method of payment or delivery, or any other circumstance that the regulated person believes may indicate that the listed chemical will be used in violation of this subchapter;"],[1,"(B) any proposed regulated transaction with a person whose description or other identifying characteristic the Attorney General furnishes in advance to the regulated person;"],[1,"(C) any unusual or excessive loss or disappearance of a listed chemical under the control of the regulated person; and"],[1,"(D) any regulated transaction in a tableting machine or an encapsulating machine."],[0,"Each report under subparagraph (A) shall be made at the earliest practicable opportunity after the regulated person becomes aware of the circumstance involved. A regulated person may not complete a transaction with a person whose description or identifying characteristic is furnished to the regulated person under subparagraph (B) unless the transaction is approved by the Attorney General. The Attorney General shall make available to regulated persons guidance documents describing transactions and circumstances for which reports are required under subparagraph (A) and subparagraph (C)."],[0,"(2) A regulated person that manufactures a listed chemical shall report annually to the Attorney General, in such form and manner and containing such specific data as the Attorney General shall prescribe by regulation, information concerning listed chemicals manufactured by the person. The requirement of the preceding sentence shall not apply to the manufacture of a drug product that is exempted under section 802(39)(A)(iv) of this title."],[0,"(3) Mail order reporting.—(A) As used in this paragraph:"],[1,"(i) The term \"drug product\" means an active ingredient in dosage form that has been approved or otherwise may be lawfully marketed under the Food, Drug, and Cosmetic Act 1 [21 U.S.C. 301 et seq.] for distribution in the United States."],[1,"(ii) The term \"valid prescription\" means a prescription which is issued for a legitimate medical purpose by an individual practitioner licensed by law to administer and prescribe the drugs concerned and acting in the usual course of the practitioner's professional practice."],[0,"(B) Each regulated person who engages in a transaction with a nonregulated person or who engages in an export transaction which—"],[1,"(i) involves ephedrine, pseudoephedrine, or phenylpropanolamine (including drug products containing these chemicals); and"],[1,"(ii) uses or attempts to use the Postal Service or any private or commercial carrier;"],[0,"shall, on a monthly basis, submit a report of each such transaction conducted during the previous month to the Attorney General in such form, containing such data, and at such times as the Attorney General shall establish by regulation."],[0,"(C) The data required for such reports shall include—"],[1,"(i) the name of the purchaser;"],[1,"(ii) the quantity and form of the ephedrine, pseudoephedrine, or phenylpropanolamine purchased; and"],[1,"(iii) the address to which such ephedrine, pseudoephedrine, or phenylpropanolamine was sent."],[0,"(D) Except as provided in subparagraph (E), the following distributions to a nonregulated person, and the following export transactions, shall not be subject to the reporting requirement in subparagraph (B):"],[1,"(i) Distributions of sample packages of drug products when such packages contain not more than two solid dosage units or the equivalent of two dosage units in liquid form, not to exceed 10 milliliters of liquid per package, and not more than one package is distributed to an individual or residential address in any 30-day period."],[1,"(ii) Distributions of drug products by retail distributors that may not include face-to-face transactions to the extent that such distributions are consistent with the activities authorized for a retail distributor as specified in section 802(49) of this title, except that this clause does not apply to sales of scheduled listed chemical products at retail."],[1,"(iii) Distributions of drug products to a resident of a long term care facility (as that term is defined in regulations prescribed by the Attorney General) or distributions of drug products to a long term care facility for dispensing to or for use by a resident of that facility."],[1,"(iv) Distributions of drug products pursuant to a valid prescription."],[1,"(v) Exports which have been reported to the Attorney General pursuant to section 954 or 971 of this title or which are subject to a waiver granted under section 971(f)(2) of this title."],[1,"(vi) Any quantity, method, or type of distribution or any quantity, method, or type of distribution of a specific listed chemical (including specific formulations or drug products) or of a group of listed chemicals (including specific formulations or drug products) which the Attorney General has excluded by regulation from such reporting requirement on the basis that such reporting is not necessary for the enforcement of this subchapter or subchapter II."],[0,"(E) The Attorney General may revoke any or all of the exemptions listed in subparagraph (D) for an individual regulated person if he finds that drug products distributed by the regulated person are being used in violation of this subchapter or subchapter II. The regulated person shall be notified of the revocation, which will be effective upon receipt by the person of such notice, as provided in section 971(c)(1) of this title, and shall have the right to an expedited hearing as provided in section 971(c)(2) of this title."],[0,"(c) Confidentiality of information obtained by Attorney General; non-disclosure; exceptions"],[0,"(1) Except as provided in paragraph (2), any information obtained by the Attorney General under this section which is exempt from disclosure under section 552(a) of title 5, by reason of section 552(b)(4) of such title, is confidential and may not be disclosed to any person."],[0,"(2) Information referred to in paragraph (1) may be disclosed only—"],[1,"(A) to an officer or employee of the United States engaged in carrying out this subchapter, subchapter II, or the customs laws;"],[1,"(B) when relevant in any investigation or proceeding for the enforcement of this subchapter, subchapter II, or the customs laws;"],[1,"(C) when necessary to comply with an obligation of the United States under a treaty or other international agreement; or"],[1,"(D) to a State or local official or employee in conjunction with the enforcement of controlled substances laws or chemical control laws."],[0,"(3) The Attorney General shall—"],[1,"(A) take such action as may be necessary to prevent unauthorized disclosure of information by any person to whom such information is disclosed under paragraph (2); and"],[1,"(B) issue guidelines that limit, to the maximum extent feasible, the disclosure of proprietary business information, including the names or identities of United States exporters of listed chemicals, to any person to whom such information is disclosed under paragraph (2)."],[0,"(4) Any person who is aggrieved by a disclosure of information in violation of this section may bring a civil action against the violator for appropriate relief."],[0,"(5) Notwithstanding paragraph (4), a civil action may not be brought under such paragraph against investigative or law enforcement personnel of the Drug Enforcement Administration."],[0,"(d) Scheduled listed chemicals; restrictions on sales quantity; requirements regarding nonliquid forms"],[0,"With respect to ephedrine base, pseudoephedrine base, or phenylpropanolamine base in a scheduled listed chemical product—"],[1,"(1) the quantity of such base sold at retail in such a product by a regulated seller, or a distributor required to submit reports by subsection (b)(3) may not, for any purchaser, exceed a daily amount of 3.6 grams, without regard to the number of transactions; and"],[1,"(2) such a seller or distributor may not sell such a product in nonliquid form (including gel caps) at retail unless the product is packaged in blister packs, each blister containing not more than 2 dosage units, or where the use of blister packs is technically infeasible, the product is packaged in unit dose packets or pouches."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/830?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§830. Regulation of listed chemicals and certain machines","tname":"Food and Drugs","by":{"1":"17, 17, 5, 18, 17"}},{"t":"law","label":"Pub. L. No. 91-513","url":"https://www.govinfo.gov/link/statute/84/1236","by":{"1":"34"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","subs":["(b)(1)","(b)(2)(B)","(b)(3)(B)","(b)(4)(B)","(b)(5)(B)","(c)"],"stext":{"head":"§812. Schedules of controlled substances","paras":[[0,"(a) Establishment"],[0,"There are established five schedules of controlled substances, to be known as schedules I, II, III, IV, and V. Such schedules shall initially consist of the substances listed in this section. The schedules established by this section shall be updated and republished on a semiannual basis during the two-year period beginning one year after October 27, 1970, and shall be updated and republished on an annual basis thereafter.1"],[0,"(b) Placement on schedules; findings required"],[0,"Except where control is required by United States obligations under an international treaty, convention, or protocol, in effect on October 27, 1970, and except in the case of an immediate precursor, a drug or other substance may not be placed in any schedule unless the findings required for such schedule are made with respect to such drug or other substance. The findings required for each of the schedules are as follows:"],[0,"(1) Schedule I.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has no currently accepted medical use in treatment in the United States."],[1,"(C) There is a lack of accepted safety for use of the drug or other substance under medical supervision."],[0,"(2) Schedule II.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States or a currently accepted medical use with severe restrictions."],[1,"(C) Abuse of the drug or other substances may lead to severe psychological or physical dependence."],[0,"(3) Schedule III.—"],[1,"(A) The drug or other substance has a potential for abuse less than the drugs or other substances in schedules I and II."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to moderate or low physical dependence or high psychological dependence."],[0,"(4) Schedule IV.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule III."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule III."],[0,"(5) Schedule V.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule IV."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule IV."],[0,"(c) Initial schedules of controlled substances"],[0,"Schedules I, II, III, IV, and V shall, unless and until amended pursuant to section 811 of this title, consist of the following drugs or other substances,1 by whatever official name, common or usual name, chemical name, or brand name designated:"],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation:"],[1,"(1) Acetylmethadol."],[1,"(2) Allylprodine."],[1,"(3) Alphacetylmathadol.2"],[1,"(4) Alphameprodine."],[1,"(5) Alphamethadol."],[1,"(6) Benzethidine."],[1,"(7) Betacetylmethadol."],[1,"(8) Betameprodine."],[1,"(9) Betamethadol."],[1,"(10) Betaprodine."],[1,"(11) Clonitazene."],[1,"(12) Dextromoramide."],[1,"(13) Dextrorphan."],[1,"(14) Diampromide."],[1,"(15) Diethylthiambutene."],[1,"(16) Dimenoxadol."],[1,"(17) Dimepheptanol."],[1,"(18) Dimethylthiambutene."],[1,"(19) Dioxaphetyl butyrate."],[1,"(20) Dipipanone."],[1,"(21) Ethylmethylthiambutene."],[1,"(22) Etonitazene."],[1,"(23) Etoxeridine."],[1,"(24) Furethidine."],[1,"(25) Hydroxypethidine."],[1,"(26) Ketobemidone."],[1,"(27) Levomoramide."],[1,"(28) Levophenacylmorphan."],[1,"(29) Morpheridine."],[1,"(30) Noracymethadol."],[1,"(31) Norlevorphanol."],[1,"(32) Normethadone."],[1,"(33) Norpipanone."],[1,"(34) Phenadoxone."],[1,"(35) Phenampromide."],[1,"(36) Phenomorphan."],[1,"(37) Phenoperidine."],[1,"(38) Piritramide."],[1,"(39) Proheptazine."],[1,"(40) Properidine."],[1,"(41) Racemoramide."],[1,"(42) Trimeperidine."],[0,"(b) Unless specifically excepted or unless listed in another schedule, any of the following opium derivatives, their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) Acetorphine."],[1,"(2) Acetyldihydrocodeine."],[1,"(3) Benzylmorphine."],[1,"(4) Codeine methylbromide."],[1,"(5) Codeine-N-Oxide."],[1,"(6) Cyprenorphine."],[1,"(7) Desomorphine."],[1,"(8) Dihydromorphine."],[1,"(9) Etorphine."],[1,"(10) Heroin."],[1,"(11) Hydromorphinol."],[1,"(12) Methyldesorphine."],[1,"(13) Methylhydromorphine."],[1,"(14) Morphine methylbromide."],[1,"(15) Morphine methylsulfonate."],[1,"(16) Morphine-N-Oxide."],[1,"(17) Myrophine."],[1,"(18) Nicocodeine."],[1,"(19) Nicomorphine."],[1,"(20) Normorphine."],[1,"(21) Pholcodine."],[1,"(22) Thebacon."],[0,"(c) Unless specifically excepted or unless listed in another schedule, any material, compound, mixture, or preparation, which contains any quantity of the following hallucinogenic substances, or which contains any of their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) 3,4-methylenedioxy amphetamine."],[1,"(2) 5-methoxy-3,4-methylenedioxy amphetamine."],[1,"(3) 3,4,5-trimethoxy amphetamine."],[1,"(4) Bufotenine."],[1,"(5) Diethyltryptamine."],[1,"(6) Dimethyltryptamine."],[1,"(7) 4-methyl-2,5-dimethoxyamphetamine."],[1,"(8) Ibogaine."],[1,"(9) Lysergic acid diethylamide."],[1,"(10) Marihuana."],[1,"(11) Mescaline."],[1,"(12) Peyote."],[1,"(13) N-ethyl-3-piperidyl benzilate."],[1,"(14) N-methyl-3-piperidyl benzilate."],[1,"(15) Psilocybin."],[1,"(16) Psilocyn."],[1,"(17) Tetrahydrocannabinols, except for tetrahydrocannabinols in hemp (as defined under section 1639o of title 7)."],[1,"(18) 4-methylmethcathinone (Mephedrone)."],[1,"(19) 3,4-methylenedioxypyrovalerone (MDPV)."],[1,"(20) 2-(2,5-Dimethoxy-4-ethylphenyl)ethanamine (2C–E)."],[1,"(21) 2-(2,5-Dimethoxy-4-methylphenyl)ethanamine (2C–D)."],[1,"(22) 2-(4-Chloro-2,5-dimethoxyphenyl)ethanamine (2C–C)."],[1,"(23) 2-(4-Iodo-2,5-dimethoxyphenyl)ethanamine (2C–I)."],[1,"(24) 2-[4-(Ethylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–2)."],[1,"(25) 2-[4-(Isopropylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–4)."],[1,"(26) 2-(2,5-Dimethoxyphenyl)ethanamine (2C–H)."],[1,"(27) 2-(2,5-Dimethoxy-4-nitro-phenyl)ethanamine (2C–N)."],[1,"(28) 2-(2,5-Dimethoxy-4-(n)-propylphenyl)ethanamine (2C–P)."],[0,"(d)(1) Unless specifically exempted or unless listed in another schedule, any material, compound, mixture, or preparation which contains any quantity of cannabimimetic agents, or which contains their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation."],[0,"(2) In paragraph (1):"],[1,"(A) The term \"cannabimimetic agents\" means any substance that is a cannabinoid receptor type 1 (CB1 receptor) agonist as demonstrated by binding studies and functional assays within any of the following structural classes:"],[2,"(i) 2-(3-hydroxycyclohexyl)phenol with substitution at the 5-position of the phenolic ring by alkyl or alkenyl, whether or not substituted on the cyclohexyl ring to any extent."],[2,"(ii) 3-(1-naphthoyl)indole or 3-(1-naphthylmethane)indole by substitution at the nitrogen atom of the indole ring, whether or not further substituted on the indole ring to any extent, whether or not substituted on the naphthoyl or naphthyl ring to any extent."],[2,"(iii) 3-(1-naphthoyl)pyrrole by substitution at the nitrogen atom of the pyrrole ring, whether or not further substituted in the pyrrole ring to any extent, whether or not substituted on the naphthoyl ring to any extent."],[2,"(iv) 1-(1-naphthylmethylene)indene by substitution of the 3-position of the indene ring, whether or not further substituted in the indene ring to any extent, whether or not substituted on the naphthyl ring to any extent."],[2,"(v) 3-phenylacetylindole or 3-benzoylindole by substitution at the nitrogen atom of the indole ring, whether or not further substituted in the indole ring to any extent, whether or not substituted on the phenyl ring to any extent."],[1,"(B) Such term includes—"],[2,"(i) 5-(1,1-dimethylheptyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (CP–47,497);"],[2,"(ii) 5-(1,1-dimethyloctyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (cannabicyclohexanol or CP–47,497 C8-homolog);"],[2,"(iii) 1-pentyl-3-(1-naphthoyl)indole (JWH–018 and AM678);"],[2,"(iv) 1-butyl-3-(1-naphthoyl)indole (JWH–073);"],[2,"(v) 1-hexyl-3-(1-naphthoyl)indole (JWH–019);"],[2,"(vi) 1-[2-(4-morpholinyl)ethyl]-3-(1-naphthoyl)indole (JWH–200);"],[2,"(vii) 1-pentyl-3-(2-methoxyphenylacetyl)indole (JWH–250);"],[2,"(viii) 1-pentyl-3-[1-(4-methoxynaphthoyl)]indole (JWH–081);"],[2,"(ix) 1-pentyl-3-(4-methyl-1-naphthoyl)indole (JWH–122);"],[2,"(x) 1-pentyl-3-(4-chloro-1-naphthoyl)indole (JWH–398);"],[2,"(xi) 1-(5-fluoropentyl)-3-(1-naphthoyl)indole (AM2201);"],[2,"(xii) 1-(5-fluoropentyl)-3-(2-iodobenzoyl)indole (AM694);"],[2,"(xiii) 1-pentyl-3-[(4-methoxy)-benzoyl]indole (SR–19 and RCS–4);"],[2,"(xiv) 1-cyclohexylethyl-3-(2-methoxyphenylacetyl)indole (SR–18 and RCS–8); and"],[2,"(xv) 1-pentyl-3-(2-chlorophenylacetyl)indole (JWH–203)."],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following substances whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/812?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§812. Schedules of controlled substances","tname":"Food and Drugs","by":{"1":"21, 21, 3, 5, 15, 30, 3, 5, 15, 3, 5, 15, 3, 5, 15, 21"}},{"t":"usc","label":"21 U.S.C. § 824","url":"https://www.law.cornell.edu/uscode/text/21/824","subs":["(a)(4)"],"stext":{"head":"§824. Denial, revocation, or suspension of registration","paras":[[0,"(a) Grounds"],[0,"A registration pursuant to section 823 of this title to manufacture, distribute, or dispense a controlled substance or a list I chemical may be suspended or revoked by the Attorney General upon a finding that the registrant—"],[1,"(1) has materially falsified any application filed pursuant to or required by this subchapter or subchapter II;"],[1,"(2) has been convicted of a felony under this subchapter or subchapter II or any other law of the United States, or of any State, relating to any substance defined in this subchapter as a controlled substance or a list I chemical;"],[1,"(3) has had his State license or registration suspended, revoked, or denied by competent State authority and is no longer authorized by State law to engage in the manufacturing, distribution, or dispensing of controlled substances or list I chemicals or has had the suspension, revocation, or denial of his registration recommended by competent State authority;"],[1,"(4) has committed such acts as would render his registration under section 823 of this title inconsistent with the public interest as determined under such section; or"],[1,"(5) has been excluded (or directed to be excluded) from participation in a program pursuant to section 1320a–7(a) of title 42."],[0,"A registration pursuant to section 823(h)(1) 1 of this title to dispense a narcotic drug for maintenance treatment or detoxification treatment may be suspended or revoked by the Attorney General upon a finding that the registrant has failed to comply with any standard referred to in section 823(h)(1) 1 of this title."],[0,"(b) Limits of revocation or suspension"],[0,"The Attorney General may limit revocation or suspension of a registration to the particular controlled substance or list I chemical with respect to which grounds for revocation or suspension exist."],[0,"(c) Service of show cause order; proceedings"],[0,"(1) Before taking action pursuant to this section, or pursuant to a denial of registration under section 823 of this title, the Attorney General shall serve upon the applicant or registrant an order to show cause why registration should not be denied, revoked, or suspended."],[0,"(2) An order to show cause under paragraph (1) shall—"],[1,"(A) contain a statement of the basis for the denial, revocation, or suspension, including specific citations to any laws or regulations alleged to be violated by the applicant or registrant;"],[1,"(B) direct the applicant or registrant to appear before the Attorney General at a time and place stated in the order, but not less than 30 days after the date of receipt of the order; and"],[1,"(C) notify the applicant or registrant of the opportunity to submit a corrective action plan on or before the date of appearance."],[0,"(3) Upon review of any corrective action plan submitted by an applicant or registrant pursuant to paragraph (2), the Attorney General shall determine whether denial, revocation, or suspension proceedings should be discontinued, or deferred for the purposes of modification, amendment, or clarification to such plan."],[0,"(4) Proceedings to deny, revoke, or suspend shall be conducted pursuant to this section in accordance with subchapter II of chapter 5 of title 5. Such proceedings shall be independent of, and not in lieu of, criminal prosecutions or other proceedings under this subchapter or any other law of the United States."],[0,"(5) The requirements of this subsection shall not apply to the issuance of an immediate suspension order under subsection (d)."],[0,"(d) Suspension of registration in cases of imminent danger"],[0,"(1) The Attorney General may, in his discretion, suspend any registration simultaneously with the institution of proceedings under this section, in cases where he finds that there is an imminent danger to the public health or safety. A failure to comply with a standard referred to in section 823(h)(1) 1 of this title may be treated under this subsection as grounds for immediate suspension of a registration granted under such section. A suspension under this subsection shall continue in effect until the conclusion of such proceedings, including judicial review thereof, unless sooner withdrawn by the Attorney General or dissolved by a court of competent jurisdiction."],[0,"(2) In this subsection, the phrase \"imminent danger to the public health or safety\" means that, due to the failure of the registrant to maintain effective controls against diversion or otherwise comply with the obligations of a registrant under this subchapter or subchapter II, there is a substantial likelihood of an immediate threat that death, serious bodily harm, or abuse of a controlled substance will occur in the absence of an immediate suspension of the registration."],[0,"(e) Suspension and revocation of quotas"],[0,"The suspension or revocation of a registration under this section shall operate to suspend or revoke any quota applicable under section 826 of this title."],[0,"(f) Disposition of controlled substances or list I chemicals"],[0,"In the event the Attorney General suspends or revokes a registration granted under section 823 of this title, all controlled substances or list I chemicals owned or possessed by the registrant pursuant to such registration at the time of suspension or the effective date of the revocation order, as the case may be, may, in the discretion of the Attorney General, be placed under seal. No disposition may be made of any controlled substances or list I chemicals under seal until the time for taking an appeal has elapsed or until all appeals have been concluded except that a court, upon application therefor, may at any time order the sale of perishable controlled substances or list I chemicals. Any such order shall require the deposit of the proceeds of the sale with the court. Upon a revocation order becoming final, all such controlled substances or list I chemicals (or proceeds of sale deposited in court) shall be forfeited to the United States; and the Attorney General shall dispose of such controlled substances or list I chemicals in accordance with section 881(e) of this title. All right, title, and interest in such controlled substances or list I chemicals shall vest in the United States upon a revocation order becoming final."],[0,"(g) Seizure or placement under seal of controlled substances or list I chemicals"],[0,"The Attorney General may, in his discretion, seize or place under seal any controlled substances or list I chemicals owned or possessed by a registrant whose registration has expired or who has ceased to practice or do business in the manner contemplated by his registration. Such controlled substances or list I chemicals shall be held for the benefit of the registrant, or his successor in interest. The Attorney General shall notify a registrant, or his successor in interest, who has any controlled substance or list I chemical seized or placed under seal of the procedures to be followed to secure the return of the controlled substance or list I chemical and the conditions under which it will be returned. The Attorney General may not dispose of any controlled substance or list I chemical seized or placed under seal under this subsection until the expiration of one hundred and eighty days from the date such substance or chemical was seized or placed under seal."],[0,"(h) Order to prohibit registration based on prior history"],[0,"The Attorney General may issue an order to prohibit, conditionally or unconditionally, and permanently or for such period as the Attorney General may determine, any person from being registered under this subchapter to manufacture, distribute, or dispense a controlled substance or a list I chemical, if the Attorney General finds that—"],[1,"(1) such person meets or has met any of the conditions for suspension or revocation of registration under subsection (a); and"],[1,"(2) such person has a history of prior suspensions or revocations of registration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/824?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§824. Denial, revocation, or suspension of registration","tname":"Food and Drugs","by":{"1":"2, 46"}},{"t":"usc","label":"21 U.S.C. § 828","url":"https://www.law.cornell.edu/uscode/text/21/828","subs":["(a)"],"by":{"1":"21"}},{"t":"usc","label":"21 U.S.C. § 829","url":"https://www.law.cornell.edu/uscode/text/21/829","subs":["(b)","(c)"],"stext":{"head":"§829. Prescriptions","paras":[[0,"(a) Schedule II substances"],[0,"Except when dispensed directly by a practitioner, other than a pharmacist, to an ultimate user, no controlled substance in schedule II, which is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], may be dispensed without the written prescription of a practitioner, except that in emergency situations, as prescribed by the Secretary by regulation after consultation with the Attorney General, such drug may be dispensed upon oral prescription in accordance with section 503(b) of that Act [21 U.S.C. 353(b)]. Prescriptions shall be retained in conformity with the requirements of section 827 of this title. No prescription for a controlled substance in schedule II may be refilled."],[0,"(b) Schedule III and IV substances"],[0,"Except when dispensed directly by a practitioner, other than a pharmacist, to an ultimate user, no controlled substance in schedule III or IV, which is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], may be dispensed without a written or oral prescription in conformity with section 503(b) of that Act [21 U.S.C. 353(b)]. Such prescriptions may not be filled or refilled more than six months after the date thereof or be refilled more than five times after the date of the prescription unless renewed by the practitioner."],[0,"(c) Schedule V substances"],[0,"No controlled substance in schedule V which is a drug may be distributed or dispensed other than for a medical purpose."],[0,"(d) Non-prescription drugs with abuse potential"],[0,"Whenever it appears to the Attorney General that a drug not considered to be a prescription drug under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] should be so considered because of its abuse potential, he shall so advise the Secretary and furnish to him all available data relevant thereto."],[0,"(e) Controlled substances dispensed by means of the Internet"],[0,"(1) No controlled substance that is a prescription drug as determined under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] may be delivered, distributed, or dispensed by means of the Internet without a valid prescription."],[0,"(2) As used in this subsection:"],[1,"(A) The term \"valid prescription\" means a prescription that is issued for a legitimate medical purpose in the usual course of professional practice by—"],[2,"(i) a practitioner who has conducted at least 1 in-person medical evaluation of the patient; or"],[2,"(ii) a covering practitioner."],[1,"(B)(i) The term \"in-person medical evaluation\" means a medical evaluation that is conducted with the patient in the physical presence of the practitioner, without regard to whether portions of the evaluation are conducted by other health professionals."],[1,"(ii) Nothing in clause (i) shall be construed to imply that 1 in-person medical evaluation demonstrates that a prescription has been issued for a legitimate medical purpose within the usual course of professional practice."],[1,"(C) The term \"covering practitioner\" means, with respect to a patient, a practitioner who conducts a medical evaluation (other than an in-person medical evaluation) at the request of a practitioner who—"],[2,"(i) has conducted at least 1 in-person medical evaluation of the patient or an evaluation of the patient through the practice of telemedicine, within the previous 24 months; and"],[2,"(ii) is temporarily unavailable to conduct the evaluation of the patient."],[0,"(3) Nothing in this subsection shall apply to—"],[1,"(A) the delivery, distribution, or dispensing of a controlled substance by a practitioner engaged in the practice of telemedicine; or"],[1,"(B) the dispensing or selling of a controlled substance pursuant to practices as determined by the Attorney General by regulation, which shall be consistent with effective controls against diversion."],[0,"(f) Partial fills of schedule II controlled substances"],[0,"(1) Partial fills"],[1,"A prescription for a controlled substance in schedule II may be partially filled if—"],[2,"(A) it is not prohibited by State law;"],[2,"(B) the prescription is written and filled in accordance with this subchapter, regulations prescribed by the Attorney General, and State law;"],[2,"(C) the partial fill is requested by the patient or the practitioner that wrote the prescription; and"],[2,"(D) the total quantity dispensed in all partial fillings does not exceed the total quantity prescribed."],[0,"(2) Remaining portions"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), remaining portions of a partially filled prescription for a controlled substance in schedule II—"],[3,"(i) may be filled; and"],[3,"(ii) shall be filled not later than 30 days after the date on which the prescription is written."],[0,"(B) Emergency situations"],[2,"In emergency situations, as described in subsection (a), the remaining portions of a partially filled prescription for a controlled substance in schedule II—"],[3,"(i) may be filled; and"],[3,"(ii) shall be filled not later than 72 hours after the prescription is issued."],[0,"(3) Currently lawful partial fills"],[1,"Notwithstanding paragraph (1) or (2), in any circumstance in which, as of the day before July 22, 2016, a prescription for a controlled substance in schedule II may be lawfully partially filled, the Attorney General may allow such a prescription to be partially filled."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/829?type=usc&year=mostrecent&link-type=html"},"op":16,"head":"§829. Prescriptions","tname":"Food and Drugs","by":{"1":"21, 16, 17, 16"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)","(a)(1)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"1":"2, 15, 26, 3, 15"}},{"t":"usc","label":"21 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/21/844","subs":["(a)"],"stext":{"head":"§844. Penalties for simple possession","paras":[[0,"(a) Unlawful acts; penalties"],[0,"It shall be unlawful for any person knowingly or intentionally to possess a controlled substance unless such substance was obtained directly, or pursuant to a valid prescription or order, from a practitioner, while acting in the course of his professional practice, or except as otherwise authorized by this subchapter or subchapter II. It shall be unlawful for any person knowingly or intentionally to possess any list I chemical obtained pursuant to or under authority of a registration issued to that person under section 823 of this title or section 958 of this title if that registration has been revoked or suspended, if that registration has expired, or if the registrant has ceased to do business in the manner contemplated by his registration. It shall be unlawful for any person to knowingly or intentionally purchase at retail during a 30 day period more than 9 grams of ephedrine base, pseudoephedrine base, or phenylpropanolamine base in a scheduled listed chemical product, except that, of such 9 grams, not more than 7.5 grams may be imported by means of shipping through any private or commercial carrier or the Postal Service. Any person who violates this subsection may be sentenced to a term of imprisonment of not more than 1 year, and shall be fined a minimum of $1,000, or both, except that if he commits such offense after a prior conviction under this subchapter or subchapter II, or a prior conviction for any drug, narcotic, or chemical offense chargeable under the law of any State, has become final, he shall be sentenced to a term of imprisonment for not less than 15 days but not more than 2 years, and shall be fined a minimum of $2,500, except, further, that if he commits such offense after two or more prior convictions under this subchapter or subchapter II, or two or more prior convictions for any drug, narcotic, or chemical offense chargeable under the law of any State, or a combination of two or more such offenses have become final, he shall be sentenced to a term of imprisonment for not less than 90 days but not more than 3 years, and shall be fined a minimum of $5,000. Notwithstanding any penalty provided in this subsection, any person convicted under this subsection for the possession of flunitrazepam shall be imprisoned for not more than 3 years, shall be fined as otherwise provided in this section, or both. The imposition or execution of a minimum sentence required to be imposed under this subsection shall not be suspended or deferred. Further, upon conviction, a person who violates this subsection shall be fined the reasonable costs of the investigation and prosecution of the offense, including the costs of prosecution of an offense as defined in sections 1918 and 1920 of title 28, except that this sentence shall not apply and a fine under this section need not be imposed if the court determines under the provision of title 18 that the defendant lacks the ability to pay."],[0,"(b) Repealed. Pub. L. 98–473, title II, §219(a), Oct. 12, 1984, 98 Stat. 2027"],[0,"(c) \"Drug, narcotic, or chemical offense\" defined"],[0,"As used in this section, the term \"drug, narcotic, or chemical offense\" means any offense which proscribes the possession, distribution, manufacture, cultivation, sale, transfer, or the attempt or conspiracy to possess, distribute, manufacture, cultivate, sell or transfer any substance the possession of which is prohibited under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/844?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§844. Penalties for simple possession","tname":"Food and Drugs","by":{"1":"15"}},{"t":"usc","label":"21 U.S.C. § 871","url":"https://www.law.cornell.edu/uscode/text/21/871","subs":["(b)"],"stext":{"head":"§871. Attorney General","paras":[[0,"(a) Delegation of functions"],[0,"The Attorney General may delegate any of his functions under this subchapter to any officer or employee of the Department of Justice."],[0,"(b) Rules and regulations"],[0,"The Attorney General may promulgate and enforce any rules, regulations, and procedures which he may deem necessary and appropriate for the efficient execution of his functions under this subchapter."],[0,"(c) Acceptance of devises, bequests, gifts, and donations"],[0,"The Attorney General may accept in the name of the Department of Justice any form of devise, bequest, gift, or donation where the donor intends to donate property for the purpose of preventing or controlling the abuse of controlled substances. He may take all appropriate steps to secure possession of such property and may sell, assign, transfer, or convey any such property other than moneys."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/871?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§871. Attorney General","tname":"Food and Drugs","by":{"1":"21"}},{"t":"usc","label":"25 U.S.C. § 1911","url":"https://www.law.cornell.edu/uscode/text/25/1911","subs":["(a)"],"by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 93-201","url":"https://www.govinfo.gov/link/statute/88/124","by":{"1":"34"}},{"t":"usc","label":"18 U.S.C. § 2312","url":"https://www.law.cornell.edu/uscode/text/18/2312","by":{"1":"25"}},{"t":"usc","label":"15 U.S.C. § 78c","url":"https://www.law.cornell.edu/uscode/text/15/78c","subs":["(a)(10)"],"by":{"1":"25"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","subs":["(g)(1)","(g)(1)(B)"],"by":{"1":"45, 45"}},{"t":"usc","label":"21 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/21/352","subs":["(j)"],"by":{"1":"42"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(d)","(i)"],"by":{"1":"42, 42"}},{"t":"usc","label":"42 U.S.C. § 290bb-2a","url":"https://www.law.cornell.edu/uscode/text/42/290bb-2a","subs":["(2000)"],"by":{"1":"32, 33, 47, 48"}},{"t":"usc","label":"42 U.S.C. § 1320c-5","url":"https://www.law.cornell.edu/uscode/text/42/1320c-5","subs":["(a)(1)","(b)"],"by":{"1":"42, 42"}},{"t":"usc","label":"42 U.S.C. § 1395y","url":"https://www.law.cornell.edu/uscode/text/42/1395y","subs":["(a)(1)(A)"],"by":{"1":"43"}},{"t":"reg","label":"28 C.F.R. § 0.1009","url":"https://www.ecfr.gov/current/title-28/section-0.1009","subs":["(b)"],"by":{"1":"23"}},{"t":"reg","label":"36 Fed. Reg. 7799","url":"https://www.govinfo.gov/link/fr/36/7799","by":{"1":"38"}},{"t":"reg","label":"64 Fed. Reg. 35,928","url":"https://www.govinfo.gov/link/fr/64/35928","by":{"1":"30"}},{"t":"reg","label":"66 Fed. Reg. 56,607","url":"https://www.govinfo.gov/link/fr/66/56607","by":{"1":"2, 27, 32, 33, 34, 45, 48"}}]};